package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

import static org.jsoup.select.Selector.SelectorParseException;
import static org.junit.jupiter.api.Assertions.*;

class ScratchNthOfTest {
    static String ids(String css, String html) {
        Document doc = Jsoup.parse(html);
        return String.join(",", doc.select(css).eachAttr("id"));
    }

    @Test void probes() {
        String html = "<div id=s><b id=x>1</b><i id=y>2</i><b id=z>3</b></div>";

        // zero step: 0n+1 only first
        assertEquals("x", ids("#s>:nth-child(0n+1 of b)", html));
        assertEquals("", ids("#s>:nth-child(0 of b)", html)); // position 0 never exists
        // nth-last zero step
        assertEquals("z", ids("#s>:nth-last-child(0n+1 of b)", html));
        // negative start -n+1
        assertEquals("x", ids("#s>:nth-child(-n+1 of b)", html));
        // legal no-match branch does not kill sibling branch
        assertEquals("y", ids(":nth-child(2 of em), i", html));
        assertEquals("x", ids(":nth-child(9 of b), b#x", html));

        // unclosed quote inside of clause -> error
        assertThrows(SelectorParseException.class, () -> Jsoup.parse(html).select(":nth-child(1 of b[title='x])"));
        // illegal escape
        assertThrows(SelectorParseException.class, () -> Jsoup.parse(html).select(":nth-child(1 of b\\:)"));
        // unexpected symbol
        assertThrows(SelectorParseException.class, () -> Jsoup.parse(html).select(":nth-child(1 of b ?? c)"));
        // nth-of-type with of is error
        assertThrows(SelectorParseException.class, () -> Jsoup.parse(html).select(":nth-of-type(1 of b)"));

        // after failure, ordinary queries on the same doc still work
        Document doc = Jsoup.parse(html);
        assertThrows(SelectorParseException.class, () -> doc.select(":nth-child(1 of )"));
        assertEquals("x,z", String.join(",", doc.select("b").eachAttr("id")));
        assertEquals("y", doc.selectFirst("#s>i:nth-child(2)").id());
        assertEquals("z", doc.selectFirst("#s b:last-child").id());

        System.out.println("ALL PROBES OK");
    }
}

